package transpile

import (
	"bytes"
	"fmt"
	"go/format"
	"path/filepath"
	"sort"
	"strings"
	"unicode"
)

// GeneratedPrefix starts every generated file. Tools use it to tell
// generated output from hand-written Go.
const GeneratedPrefix = "// Code generated by gosling"

type edit struct {
	start, end int // offsets into the preprocessed source
	text       string
	line       int // source line that generated text belongs to
	// order sorts insertions at the same offset. Opening text uses its
	// depth, so outer openings come first. Closing text uses its negative
	// depth, so inner closings come first.
	order int
	// If move is set, the text is before, then the rendered source range, then after.
	move          *[2]int
	before, after string
}

// resolvedEdit is an edit with its final text. copies records the parts of
// the text that come from the preprocessed source, with offsets into text.
type resolvedEdit struct {
	edit
	copies []copiedRange
	// movedFrom is the start of the moved source range, or -1.
	movedFrom int
}

// emit applies the edits to the preprocessed source and formats the result.
func (lowerer *lowerer) emit() ([]byte, SourceMap, error) {
	src := lowerer.file.preprocessed.Src
	edits, err := lowerer.resolve(0, len(src))
	if err != nil {
		return nil, SourceMap{}, err
	}
	writer := &outputWriter{
		src:            src,
		baseName:       filepath.Base(lowerer.file.path),
		lineDirectives: lowerer.config.LineDirectives,
	}
	writer.writeHeader(lowerer.offset(lowerer.file.ast.Package))
	for _, currentEdit := range edits {
		if currentEdit.start < writer.copiedUpTo {
			return nil, SourceMap{}, fmt.Errorf("%s: internal error: overlapping edits at offset %d", lowerer.file.path, currentEdit.start)
		}
		writer.writeEdit(currentEdit)
	}
	writer.copyOriginal(len(src))
	unformatted := writer.buffer.Bytes()
	if bytes.Contains(unformatted, []byte("__gosling")) {
		return nil, SourceMap{}, fmt.Errorf("%s: internal error: marker left in output", lowerer.file.path)
	}
	formatted, err := formatUntilStable(lowerer.file.path, unformatted)
	if err != nil {
		return nil, SourceMap{}, err
	}
	if lowerer.config.LineDirectives {
		formatted = restoreDirectiveLines(unformatted, formatted)
	}
	return formatted, buildSourceMap(lowerer.file, unformatted, writer.copies, formatted), nil
}

// outputWriter builds a generated file from the preprocessed source and the
// edits. It adds line directives so positions map back to the .gol file.
type outputWriter struct {
	buffer         bytes.Buffer
	src            []byte
	baseName       string
	lineDirectives bool
	copiedUpTo     int
	copies         []copiedRange
	// needsDirective is true after generated text adds lines. The next
	// original token then needs a directive to restore the line mapping.
	needsDirective bool
}

func (writer *outputWriter) lineAt(offset int) int {
	return 1 + bytes.Count(writer.src[:offset], []byte("\n"))
}

// directive writes a line directive for the next token. gofmt moves a
// directive that follows a comma on the same line to before the comma.
// The comma, not the next token, then gets the line. So the directive goes
// before such a comma.
func (writer *outputWriter) directive(line int) {
	if !writer.lineDirectives {
		return
	}
	output := writer.buffer.Bytes()
	insertOffset := len(bytes.TrimRight(output, " \t"))
	if insertOffset == 0 || output[insertOffset-1] != ',' {
		fmt.Fprintf(&writer.buffer, "/*line %s:%d*/", writer.baseName, line)
		return
	}
	insertOffset--
	trailingText := bytes.Clone(output[insertOffset:])
	writer.buffer.Truncate(insertOffset)
	fmt.Fprintf(&writer.buffer, "/*line %s:%d*/", writer.baseName, line)
	writer.shiftCopies(insertOffset, writer.buffer.Len()-insertOffset)
	writer.buffer.Write(trailingText)
}

// shiftCopies moves the copied ranges at or after outOffset by shift. A
// range that contains outOffset splits in two.
func (writer *outputWriter) shiftCopies(outOffset, shift int) {
	firstShiftedIndex := len(writer.copies)
	for firstShiftedIndex > 0 {
		previous := writer.copies[firstShiftedIndex-1]
		if previous.outOffset < outOffset && previous.outOffset+previous.length <= outOffset {
			break
		}
		firstShiftedIndex--
	}
	var shiftedCopies []copiedRange
	for _, copied := range writer.copies[firstShiftedIndex:] {
		if copied.outOffset < outOffset {
			headLength := outOffset - copied.outOffset
			shiftedCopies = append(shiftedCopies, copiedRange{srcOffset: copied.srcOffset, outOffset: copied.outOffset, length: headLength})
			copied = copiedRange{srcOffset: copied.srcOffset + headLength, outOffset: outOffset, length: copied.length - headLength}
		}
		copied.outOffset += shift
		shiftedCopies = append(shiftedCopies, copied)
	}
	writer.copies = append(writer.copies[:firstShiftedIndex], shiftedCopies...)
}

// writeHeader writes the generated-code notice and the source up to the
// package clause. The file-level directive goes directly before the package
// clause. Above a package doc comment, gofmt moves it below the comment and
// shifts every line.
func (writer *outputWriter) writeHeader(packageOffset int) {
	fmt.Fprintf(&writer.buffer, "%s from %s. DO NOT EDIT.\n\n", GeneratedPrefix, writer.baseName)
	writer.writeSource(0, writer.src[:packageOffset])
	if writer.lineDirectives {
		fmt.Fprintf(&writer.buffer, "//line %s:%d\n", writer.baseName, writer.lineAt(packageOffset))
	}
	writer.copiedUpTo = packageOffset
}

// copyOriginal copies source text up to offset, putting a pending line
// directive before its first token.
func (writer *outputWriter) copyOriginal(offset int) {
	from := writer.copiedUpTo
	segment := writer.src[from:offset]
	writer.copiedUpTo = offset
	firstNonSpace := bytes.IndexFunc(segment, func(char rune) bool { return !unicode.IsSpace(char) })
	if !writer.needsDirective || firstNonSpace < 0 {
		writer.writeSource(from, segment)
		return
	}
	writer.writeSource(from, segment[:firstNonSpace])
	writer.directive(writer.lineAt(from + firstNonSpace))
	writer.writeSource(from+firstNonSpace, segment[firstNonSpace:])
	writer.needsDirective = false
}

// writeSource writes text that starts at srcOffset in the preprocessed source.
func (writer *outputWriter) writeSource(srcOffset int, text []byte) {
	writer.copies = append(writer.copies, copiedRange{srcOffset: srcOffset, outOffset: writer.buffer.Len(), length: len(text)})
	writer.buffer.Write(text)
}

func (writer *outputWriter) writeEdit(currentEdit resolvedEdit) {
	writer.copyOriginal(currentEdit.start)
	if currentEdit.text != "" {
		writer.writeEditDirective(currentEdit)
	}
	textStart := writer.buffer.Len()
	firstLine, restLines, isMultiline := strings.Cut(currentEdit.text, "\n")
	writer.buffer.WriteString(firstLine)
	directiveLength := 0
	if isMultiline {
		writer.buffer.WriteString("\n")
		directiveStart := writer.buffer.Len()
		writer.directive(currentEdit.line)
		directiveLength = writer.buffer.Len() - directiveStart
		writer.buffer.WriteString(restLines)
	}
	writer.addEditCopies(currentEdit.copies, textStart, len(firstLine), directiveLength)
	if isMultiline || bytes.IndexByte(writer.src[currentEdit.start:currentEdit.end], '\n') >= 0 {
		writer.needsDirective = true
	}
	writer.copiedUpTo = currentEdit.end
}

// writeEditDirective writes a line directive before the text of an edit when
// the output line no longer matches the source. Moved code keeps the line of
// its source.
func (writer *outputWriter) writeEditDirective(currentEdit resolvedEdit) {
	nextLine := writer.lineAt(nextNonSpace(writer.src, currentEdit.start))
	isMoved := currentEdit.movedFrom >= 0
	switch {
	case isMoved && (writer.needsDirective || writer.lineAt(currentEdit.movedFrom) != nextLine):
		writer.directive(writer.lineAt(currentEdit.movedFrom))
		writer.needsDirective = false
	case writer.needsDirective:
		writer.directive(nextLine)
		writer.needsDirective = false
	}
}

// addEditCopies records the copied ranges of an edit's text. The text starts
// at textStart. A directive after the first line shifts the later ranges.
func (writer *outputWriter) addEditCopies(copies []copiedRange, textStart, firstLineLength, directiveLength int) {
	for _, copied := range copies {
		switch {
		case copied.outOffset+copied.length <= firstLineLength:
			copied.outOffset += textStart
		case copied.outOffset > firstLineLength:
			copied.outOffset += textStart + directiveLength
		default:
			continue // the range contains the newline before the directive
		}
		writer.copies = append(writer.copies, copied)
	}
}

const maxFormatPasses = 3

// formatUntilStable runs gofmt more than once. A line directive attached to
// a top-level declaration moves to its own line only on a second pass.
func formatUntilStable(path string, src []byte) ([]byte, error) {
	formatted, err := format.Source(src)
	if err != nil {
		return nil, fmt.Errorf("%s: internal error: generated code does not parse: %w\n%s", path, err, src)
	}
	for range maxFormatPasses {
		reformatted, err := format.Source(formatted)
		if err != nil {
			return nil, fmt.Errorf("%s: internal error: reformatting failed: %w", path, err)
		}
		if bytes.Equal(reformatted, formatted) {
			return formatted, nil
		}
		formatted = reformatted
	}
	return nil, fmt.Errorf("%s: internal error: gofmt output did not settle", path)
}

func (candidate edit) within(rangeStart, rangeEnd int) bool {
	return candidate.start >= rangeStart && candidate.end <= rangeEnd
}

func (candidate edit) isInsertion() bool { return candidate.start == candidate.end }

// resolve returns the sorted edits for src[from:to]. A drop replaces a whole
// region and swallows the edits in it. A move gets its text from its source
// range, with the edits of that range applied.
func (lowerer *lowerer) resolve(from, to int) ([]resolvedEdit, error) {
	drops := lowerer.dropsWithin(from, to)
	var kept []edit
	for _, currentEdit := range append(append([]edit{}, lowerer.edits...), drops...) {
		if currentEdit.within(from, to) && !swallowedByDrop(currentEdit, drops) {
			kept = append(kept, currentEdit)
		}
	}
	sortEdits(kept)
	resolved := make([]resolvedEdit, 0, len(kept))
	for _, currentEdit := range kept {
		finished := resolvedEdit{edit: currentEdit, movedFrom: -1}
		if currentEdit.move != nil {
			finished.movedFrom = currentEdit.move[0]
			moved, movedCopies, err := lowerer.render(currentEdit.move[0], currentEdit.move[1])
			if err != nil {
				return nil, err
			}
			finished.text = currentEdit.before + moved + currentEdit.after
			finished.move = nil
			finished.copies = shiftCopies(movedCopies, len(currentEdit.before))
		}
		resolved = append(resolved, finished)
	}
	return resolved, nil
}

func shiftCopies(copies []copiedRange, shift int) []copiedRange {
	shifted := make([]copiedRange, len(copies))
	for copyIndex, copied := range copies {
		copied.outOffset += shift
		shifted[copyIndex] = copied
	}
	return shifted
}

// dropsWithin returns the drops inside [from, to), except one covering
// exactly that range, which is the drop being rendered.
func (lowerer *lowerer) dropsWithin(from, to int) []edit {
	var drops []edit
	for _, drop := range lowerer.drops {
		if drop.within(from, to) && (drop.start != from || drop.end != to) {
			drops = append(drops, drop)
		}
	}
	return drops
}

// swallowedByDrop reports whether candidate is inside a drop. An insertion
// at the edge of a drop belongs to the code around it.
func swallowedByDrop(candidate edit, drops []edit) bool {
	for _, drop := range drops {
		isAtEdge := candidate.isInsertion() && (candidate.start == drop.start || candidate.start == drop.end)
		if candidate.within(drop.start, drop.end) && candidate != drop && !isAtEdge {
			return true
		}
	}
	return false
}

// sortEdits orders edits by offset. Insertions sort before replacements at
// the same offset so a removal starting there cannot swallow them.
func sortEdits(edits []edit) {
	sort.SliceStable(edits, func(leftIndex, rightIndex int) bool {
		left, right := edits[leftIndex], edits[rightIndex]
		if left.start != right.start {
			return left.start < right.start
		}
		if leftLength, rightLength := left.end-left.start, right.end-right.start; leftLength != rightLength {
			return leftLength < rightLength
		}
		return left.order < right.order
	})
}

// render returns src[from:to] with its edits applied, and the ranges of the
// result that come from src.
func (lowerer *lowerer) render(from, to int) (string, []copiedRange, error) {
	edits, err := lowerer.resolve(from, to)
	if err != nil {
		return "", nil, err
	}
	src := lowerer.file.preprocessed.Src
	var rendered strings.Builder
	var copies []copiedRange
	writeSource := func(start, end int) {
		copies = append(copies, copiedRange{srcOffset: start, outOffset: rendered.Len(), length: end - start})
		rendered.Write(src[start:end])
	}
	lastOffset := from
	for _, currentEdit := range edits {
		if currentEdit.start < lastOffset {
			return "", nil, fmt.Errorf("%s: internal error: overlapping edits at offset %d", lowerer.file.path, currentEdit.start)
		}
		writeSource(lastOffset, currentEdit.start)
		copies = append(copies, shiftCopies(currentEdit.copies, rendered.Len())...)
		rendered.WriteString(currentEdit.text)
		lastOffset = currentEdit.end
	}
	writeSource(lastOffset, to)
	return rendered.String(), copies, nil
}

func nextNonSpace(src []byte, offset int) int {
	for offset < len(src) && unicode.IsSpace(rune(src[offset])) {
		offset++
	}
	return offset
}
